package com.vk.starscriptmusic.data.local.db.entity

import androidx.room.Entity
import androidx.room.Index
import androidx.room.PrimaryKey
import com.vk.starscriptmusic.domain.model.Playlist

/**
 * Room Entity representing a custom or auto-generated artist playlist.
 */
@Entity(
    tableName = "playlists",
    indices = [
        Index(value = ["name"]),
        Index(value = ["isAutoGenerated"]),
        Index(value = ["artistFilter"])
    ]
)
data class PlaylistEntity(
    @PrimaryKey(autoGenerate = true)
    val id: Long = 0L,
    val name: String,
    val description: String? = null,
    val createdAt: Long = System.currentTimeMillis(),
    val isAutoGenerated: Boolean = false,
    val artistFilter: String? = null
) {
    fun toDomain(): Playlist {
        return Playlist(
            id = id,
            name = name,
            description = description,
            createdAt = createdAt,
            isAutoGenerated = isAutoGenerated,
            artistFilter = artistFilter,
            tracks = emptyList()
        )
    }
}
